import random
from collections import Counter
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
comp=Counter(seq)
alphabet="".join(b for b in "ACGT" for _ in range(comp[b]))
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
tab={}
bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            tab[b1+b2+b3]=aas[i]; i+=1
def longest(s):
    m=0
    for f in range(3):
        j=f;cur=None
        while j+3<=len(s):
            if tab[s[j:j+3]]=="*":
                if cur is not None: m=max(m,j-cur)
                cur=None
            else:
                if cur is None: cur=j
            j+=3
        if cur is not None: m=max(m,len(s)-cur)
    return m
def l6(s): return max(longest(s),longest(rc(s)))
obs=l6(seq)
sims=[l6("".join(random.choice(alphabet) for _ in range(n))) for _ in range(300)]
sims.sort()
print("observed longest ORF:",obs)
print("simulated mean",sum(sims)/len(sims),"max",max(sims),"95th pct",sims[int(0.95*len(sims))])
print("fraction sims >= obs", sum(1 for x in sims if x>=obs)/len(sims))
